"""Convert a URL to IDN notation. It checks if the host can be encoded in ASCII. If not, it converts the host to IDN form.

:param url: String. The URL to be converted to IDN notation.
:return: String. The URL in IDN notation.
"""
if not url:
    return url
try:
    url = url.encode("ascii")
except UnicodeEncodeError:
    url = url.encode("idna")
return url.decode("utf-8")

"""This function adds a hook to save table of contents (TOC) items into the state.env. It is usually helpful for doc generator.

:param md: Markdown instance. The instance of the Markdown class.
:param min_level: Integer. The minimum heading level to include in the TOC.
:param max_level: Integer. The maximum heading level to include in the TOC.
:param heading_id: Function. A function to generate heading_id.
:return: No return values.
"""

def _add_toc_hook(state):
    if not state.env.get("toc"):
        state.env["toc"] = []

    if not state.env.get("toc_counter"):
        state.env["toc_counter"] = {}

    if not state.env.get("toc_id"):
        state.env["toc_id"] = 0

    if not state.env.get("toc_level"):
        state.env["toc_level"] = min_level

    if not state.env.get("toc_max_level"):
        state.env["toc_max_level"] = max_level

    if not state.env.get("toc_heading_id"):
        state.env["toc_heading_id"] = heading_id

md.before_render(_add_toc_hook)

def _toc_hook(state):
    if state.level >= state.env["toc_level"] and state.level <= state.env["toc_max_level"]:
        if not state.env["toc_counter"].get(state.level):
            state.env["toc_counter"][state.level] = 0
        state.env["toc_counter"][state.level] += 1

        if state.level == 1:
            state.env["toc_id"] = 0

        if state.level > 1:
            state.env["toc_id"] += 1

        if state.level == 1:
            state.env["toc"].append(
                {
                    "id": state.env["toc_id"],
                    "level": state.level,
                    "title": state.text,
                }
            )
        else:
            state.env["toc"][-1]["children"].append(
                {
                    "id": state.env["toc_id"],
                    "level": state.level,
                    "children": [],
                    "title": state.text,
                }
            )

md.inline.register_rule("toc_hook", _toc_hook, "<text>")
